import json,hashlib,pathlib,subprocess,os
s=pathlib.Path(os.environ['TMPDIR'])/'pricing-maintenance'; r=pathlib.Path('[fixture]')
h=lambda x:hashlib.sha256(x).hexdigest()
save=lambda n,x:(s/n).write_text(json.dumps(x,indent=2)+'\n')
base=subprocess.check_output(['git','rev-parse','HEAD'],cwd=r,text=True).strip(); (s/'base').write_text(base)
contract=json.loads((r/'.bstack/project.json').read_text()); old=json.loads((r/'.bstack/assessment.json').read_text()); save('prior-assessment.json',old)
cases=[{'id':a['id'],'sourceId':'design','pointer':a['pointer'],'outcome':a['pointer'],'userJourney':True} for a in contract['acceptanceSources']]
plan={'schemaVersion':1,'changeKind':'refactor','acceptanceSources':[{'id':'design','path':'DESIGN.md','contentHash':h((r/'DESIGN.md').read_bytes())}],'acceptanceCases':cases,'checks':[{'id':'native','role':'compatibility','command':contract['checks'][0]['command'],'required':True,'acceptanceCases':[a['id'] for a in cases],'inputScopes':contract['checks'][0]['inputScopes']}]};save('checks.json',plan)
p='packages/core/internal/database.ts'; original=(r/p).read_text(); proposed=original.replace('  const total = unitPrice * quantity * (quantity > 5 ? 0.9 : 1)','  const subtotal = unitPrice * quantity\n  const total = subtotal * (quantity > 5 ? 0.9 : 1)'); assert original!=proposed
f={'schemaVersion':1,'stage':'audit','target':{'mode':'repo','root':str(r),'revision':base},'nextChange':'Authorised bounded pricing refactor naming subtotal with preserved public behaviour.','reviewedScope':[p,'.bstack/assessment.json'],'sources':[{'id':'design','pointer':'DESIGN.md','intent':'documented','summary':'Public quote 12, checkout total 10 and existing quantity calculation are approved.'}],'findings':[{'id':'F-007','problem':'The pricing calculation does not name its intermediate unit-price times quantity value.','files':[p],'command':None,'principle':'Preserve public pricing and checkout behaviour.','consequence':'The intermediate subtotal is implicit.','fix':'Name subtotal without changing multiplication order or the existing quantity multiplier.','scope':[p,'.bstack/assessment.json'],'verification':'Original-state and final aggregate native captures; fresh local and clean-clone checker.','blocksNextChange':False,'category':'debt','status':'selected','newPrinciple':False,'resolved':False,'sourceIds':['design']}],'selectedFindingIds':['F-007'],'requiredOutcomes':['journey'],'execution':[],'limitations':['Bounded maintenance selected by user; no audit, interview or delivery service.']};save('findings.json',f)
canonical=lambda x:json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()
apply={'schemaVersion':1,'target':f['target'],'findings':str(s/'findings.json'),'findingsDigest':h(canonical(f)),'selectedFindingIds':['F-007'],'reviewedScope':[{'path':p,'resolvedPath':str(r/p)}],'edits':[{'id':'pricing-subtotal','findingId':'F-007','path':p,'originalHash':h(original.encode()),'proposedHash':h(proposed.encode()),'operation':'replace-file','payload':{},'proposedContent':proposed}]};apply['planDigest']=h(canonical(apply));save('implementation-plan.json',apply)
